const useSurveyStore = defineStore('survey', {
  state: () => {
    return {
      tableId: '',
      roomNo: '',
      projectCode: '',
      projectName: '',
      title: '',
      ECode: '',
    }
  },
  actions: {
    getTableId() {
      return this.tableId
    },
    setTableId(val) {
      return this.tableId = val
    },
    getRoomNo() {
      return this.roomNo
    },
    setRoomNo(val) {
      return this.roomNo = val
    },
    getProjectCode() {
      return this.projectCode
    },
    setProjectCode(val) {
      return this.projectCode = val
    },
    getProjectName() {
      return this.projectName
    },
    setProjectName(val) {
      return this.projectName = val
    },
    getTitle() {
      return this.title
    },
    setTitle(val) {
      return this.title = val
    },
    getECode() {
      return this.ECode
    },
    setECode(val) {
      return this.ECode = val
    },
  }
})

const surveyStore = useSurveyStore(store)

const surveyStorage = uni.getStorageSync('survey')
if(isJSON(surveyStorage)) {
  const userData = JSON.parse(surveyStorage);
  surveyStore.$patch(userData);
}

surveyStore.$subscribe((mutation, state) => {
  const jsonString = JSON.stringify(state, (key, value) => {
    if (typeof value === 'function' || value === undefined) {
      return null;
    }
    return value;
  });
  uni.setStorageSync('survey', jsonString);
});

export default surveyStore
