    userAgent: 'Mozilla/5.0 (Linux; Android 11; Pixel 5) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/90.0.4430.91 Mobile Safari/537.36',
  });
  const page = await context.newPage();

  const goHandleResp = {
    MtplQuestionnaireModel: {
      description: '苏州工业园区业主（使用人）2025年度满意度抽样调查',
      totalCount: 2784,
      joinedCount: 7,
      examsList: [
        { type: 4, topic: '您对本小区物业管理服务的期望如何？', hint: '最低半颗星，满分5星', nochoisenum: 1, nochoisenumPJ: '' },
        { type: 0, topic: '单选题示例', options: ['A', 'B', 'C'], nochoisenum: 1 },
        { type: 0, topic: '第二题单选题', options: ['X', 'Y'], nochoisenum: 1 },
      ],
    },
  };
  const replyRateResp = { rate: '0.25', totalHouse: 2784, replyHouse: 7 };

  await context.route('**/*SmQuestionnaireGoHandleApp*', (route) =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(goHandleResp) }),
  );
  await context.route('**/*SmQuestionnaireReplyRate*', (route) =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(replyRateResp) }),
  );

  // seed survey store in localStorage
  const survey = { tableId: 'T1', roomNo: 'R1', projectCode: 'P1', projectName: '香堤澜湾花园', title: '民意调查', ECode: 'E1' };
  await page.addInitScript((s) => {
    window.localStorage.setItem('survey', JSON.stringify(s));
  }, survey);

  const url = 'http://localhost:8092/wechatapph5/#/pages-survey/index';
  await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(2500);

  const bodyText = await page.evaluate(() => document.body.innerText);
  console.log('=== BODY TEXT (first 600) ===');
  console.log(bodyText.slice(0, 600));

  // Check for uv-rate stars
  const rateInfo = await page.evaluate(() => {
    const el = document.querySelector('.survey-rate-wrapper');
    if (!el) return { found: false };
    const icons = el.querySelectorAll('.uv-rate__content__item, [class*="uv-rate"]');
    const html = el.innerHTML.slice(0, 400);
    const rect = el.getBoundingClientRect();
    return { found: true, childCount: el.querySelectorAll('*').length, width: rect.width, height: rect.height, html };
  });
  console.log('=== RATE INFO ===');
  console.log(JSON.stringify(rateInfo, null, 2));

  // Try clicking on the 5th star position
