  let afterClickText = '';
  if (wrapper) {
    const box = await wrapper.boundingBox();
    console.log('=== WRAPPER BOX ===', JSON.stringify(box));
    if (box) {
      // click near right side (star 5)
      await page.mouse.click(box.x + box.width * 0.9, box.y + box.height / 2);
      await page.waitForTimeout(500);
      // read next button state
