        return btns.map((b) => ({ text: b.innerText.trim(), disabled: b.classList.contains('survey-page-text-btn-disabled') }));
      });
      console.log('=== BUTTONS AFTER CLICK ===', JSON.stringify(nextInfo));
    }
  }

