        { type: 0, topic: '第三题：单选题示例', options: ['X', 'Y'], nochoisenum: 1 },
      ],
    },
  };
  const replyRateResp = { rate: '0.25', totalHouse: 2784, replyHouse: 7 };

  await context.route('**/*SmQuestionnaireGoHandleApp*', (route) =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(goHandleResp) }));
  await context.route('**/*SmQuestionnaireReplyRate*', (route) =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(replyRateResp) }));

  const survey = { tableId: 'T1', roomNo: 'R1', projectCode: 'P1', projectName: '香堤澜湾花园', title: '民意调查', ECode: 'E1' };
  await page.addInitScript((s) => { window.localStorage.setItem('survey', JSON.stringify(s)); }, survey);

  await page.goto('http://localhost:8092/wechatapph5/#/pages-survey/index', { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(2500);

  console.log('=== STEP 1: STAR question render ===');
  const step1 = await page.evaluate(() => {
    const uvrate = document.querySelector('[class*="uv-rate"]');
    const starSection = document.querySelector('.survey-page-star-section');
    const hint = document.querySelector('.survey-page-star-section .survey-page-question-hint');
    const btns = Array.from(document.querySelectorAll('.survey-page-text-btn')).map(b => ({ text: b.innerText.trim(), disabled: b.classList.contains('survey-page-text-btn-disabled') }));
    return { starSectionFound: !!starSection, uvrateFound: !!uvrate, hint: hint ? hint.innerText : null, btns };
  });
  console.log(JSON.stringify(step1, null, 2));

  console.log('=== STEP 2: click star (set rating) ===');
  const wrapper = await page.$('.survey-rate-wrapper');
  let box = wrapper ? await wrapper.boundingBox() : null;
  console.log('wrapper box', JSON.stringify(box));
  if (box) {
    await page.mouse.click(box.x + box.width * 0.7, box.y + box.height / 2);
    await page.waitForTimeout(400);
    const afterRate = await page.evaluate(() => {
      const active = document.querySelectorAll('[class*="uv-rate__content__item"] [class*="active"], [class*="uv-rate"] [style*="star-fill"]');
      const btns = Array.from(document.querySelectorAll('.survey-page-text-btn')).map(b => ({ text: b.innerText.trim(), disabled: b.classList.contains('survey-page-text-btn-disabled') }));
      return { btns };
    });
    console.log('after rating', JSON.stringify(afterRate, null, 2));

    console.log('=== STEP 3: click 下一题 ===');
    const nextBtn = await page.$('.survey-page-text-btn:not(.survey-page-text-btn-disabled)');
    // find the button containing 下一题
    const nextBtns = await page.$$('.survey-page-text-btn');
    let clickNext = null;
    for (const b of nextBtns) { const t = (await b.innerText()).trim(); if (t.includes('下一题') && !(await b.evaluate(e=>e.classList.contains('survey-page-text-btn-disabled')))) clickNext = b; }
