      const title = document.querySelector('.survey-page-question-title');
      return { pagination: pag ? pag.innerText : null, title: title ? title.innerText : null };
    });
    console.log('after next', JSON.stringify(step3, null, 2));
  }

  await page.screenshot({ path: 'D:\\tmp\\verify_final.png', fullPage: false });
  await browser.close();
})().catch((e) => { console.error('FATAL', e); process.exit(1); });

